CREATE SEQUENCE myschema.custom_seq
    INCREMENT BY 1
    MINVALUE 1
    MAXVALUE 9223372036854775807
    START WITH 1
    CACHE 1
    NO CYCLE;

-- ======================================
-- TABLES
-- ======================================

-- Table: myschema.users
CREATE TABLE myschema.users (
    user_id bigserial NOT NULL,
    username character varying(50) NOT NULL,
    email character varying(100) NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    modified_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    is_active boolean DEFAULT true NOT NULL,
    CONSTRAINT users_pkey PRIMARY KEY (user_id),
    CONSTRAINT users_email_key UNIQUE (email),
    CONSTRAINT users_username_key UNIQUE (username),
    CONSTRAINT users_email_check CHECK ((length((email)::text) > 5))
);
COMMENT ON COLUMN myschema.users.user_id IS 'Primary key for users table';
COMMENT ON COLUMN myschema.users.email IS 'User email address, must be unique';
COMMENT ON TABLE myschema.users IS 'Stores user account information';

-- Table: myschema.profiles
CREATE TABLE myschema.profiles (
    profile_id bigserial NOT NULL,
    user_id bigint NOT NULL,
    first_name character varying(50),
    last_name character varying(50),
    bio text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT profiles_pkey PRIMARY KEY (profile_id),
    CONSTRAINT profiles_user_id_key UNIQUE (user_id)
);

-- Table: myschema.posts
CREATE TABLE myschema.posts (
    post_id bigserial NOT NULL,
    user_id bigint NOT NULL,
    title character varying(200) NOT NULL,
    content text,
    status character varying(20) DEFAULT 'draft'::character varying,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    modified_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT posts_pkey PRIMARY KEY (post_id),
    CONSTRAINT posts_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'published'::character varying, 'archived'::character varying])::text[])))
);

-- Table: myschema.comments
CREATE TABLE myschema.comments (
    comment_id bigserial NOT NULL,
    post_id bigint NOT NULL,
    user_id bigint NOT NULL,
    content text NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT comments_pkey PRIMARY KEY (comment_id)
);

