-- Trigger: myschema.users_update_modified_timestamp
CREATE TRIGGER users_update_modified_timestamp BEFORE UPDATE ON myschema.users FOR EACH ROW EXECUTE FUNCTION myschema.update_modified_timestamp();

-- Trigger: myschema.posts_update_modified_timestamp
CREATE TRIGGER posts_update_modified_timestamp BEFORE UPDATE ON myschema.posts FOR EACH ROW EXECUTE FUNCTION myschema.update_modified_timestamp();

-- ======================================
-- VIEWS
-- ======================================

-- View: myschema.v_user_posts
CREATE OR REPLACE VIEW myschema.v_user_posts AS
SELECT 
    u.user_id,
    u.username,
    p.post_id,
    p.title,
    p.status,
    p.created_at
FROM myschema.users u
JOIN myschema.posts p ON u.user_id = p.user_id
WHERE p.status = 'published'::character varying;

-- View: myschema.v_post_stats
CREATE OR REPLACE VIEW myschema.v_post_stats AS
SELECT 
    p.post_id,
    p.title,
    p.user_id,
    COUNT(c.comment_id) AS comment_count,
    MAX(c.created_at) AS last_comment_at
FROM myschema.posts p
LEFT JOIN myschema.comments c ON p.post_id = c.post_id
GROUP BY p.post_id, p.title, p.user_id;
